def algorithm(func, dim, lb, ub, budget, rng):
    best_solution = np.zeros(dim)
    best_value = float('inf')

    for _ in range(budget):
        candidate = (ub - lb) * rng.rand(dim) + lb
        value = func(candidate)

        if value < best_value:
            best_solution = candidate
            best_value = value

    return best_solution

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = np.zeros(dim)
    best_f = float('inf')

    for _ in range(budget):
        x = lb + (ub - lb) * rng.rand(dim)

        f = func(x)

        if f < best_f:
            best_f = f
            best_x = x

    return best_x
